"""Summarize node sequence files without changing them."""
import json
import os
from pathlib import Path
import re
import stat
import sys


CHANNELS = ("obs", "must")


def strict_json(raw):
    def reject_constant(value):
        raise ValueError(value)

    return json.loads(raw, parse_constant=reject_constant)


def channel_summary(root, channel, names, bad):
    pattern = re.compile(re.escape(channel) + r"\.([0-9]{12})\.jsonl\Z")
    numbered = sorted(
        ((int(match.group(1)), name) for name in names
         if (match := pattern.fullmatch(name))),
        key=lambda item: item[0],
    )
    files = [name for _, name in numbered]
    active = channel + ".active.jsonl"
    if active in names:
        files.append(active)

    sequences = []
    for name in files:
        parts = (root / name).read_bytes().split(b"\n")
        for line_number, raw in enumerate(parts[:-1], 1):
            try:
                record = strict_json(raw)
            except (ValueError, UnicodeError):
                bad.append({"file": name, "line": line_number, "why": "bad_json"})
                continue
            seq = record.get("seq") if isinstance(record, dict) else None
            if type(seq) is not int or seq < 1:
                bad.append({"file": name, "line": line_number, "why": "no_seq"})
            else:
                sequences.append(seq)
        if parts[-1]:
            bad.append({"file": name, "line": len(parts), "why": "torn"})

    ordered = sorted(set(sequences))
    frequencies = {}
    for seq in sequences:
        frequencies[seq] = frequencies.get(seq, 0) + 1
    return {
        "count": len(sequences),
        "first": ordered[0] if ordered else None,
        "last": ordered[-1] if ordered else None,
        "missing": [[left + 1, right - 1] for left, right in zip(ordered, ordered[1:])
                    if right > left + 1],
        "dup": sorted(seq for seq, count in frequencies.items() if count >= 2),
        "next_seq": None,
        "unacked": None,
        "stale_next": None,
    }, ordered


def apply_state(root, channels, distinct, bad):
    path = root / "state.json"
    try:
        mode = os.lstat(path).st_mode
    except FileNotFoundError:
        return
    try:
        if not stat.S_ISREG(mode):
            raise ValueError("state is not a regular file")
        state = strict_json(path.read_bytes())
        if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
            raise ValueError("invalid state structure")
        fields = state["channels"]
        if any(not isinstance(fields.get(channel), dict) for channel in CHANNELS):
            raise ValueError("invalid channel structure")
    except (OSError, ValueError, UnicodeError):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return

    invalid = False
    for channel in CHANNELS:
        values = fields[channel]
        next_seq = values.get("next_seq")
        acked = values.get("acked_upto") if channel == "must" else None
        if type(next_seq) is not int or (channel == "must" and type(acked) is not int):
            invalid = True
            continue
        summary = channels[channel]
        summary["next_seq"] = next_seq
        summary["stale_next"] = (next_seq != summary["last"] + 1
                                 if summary["last"] is not None else None)
        if channel == "must":
            summary["unacked"] = sum(seq > acked for seq in distinct[channel])
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})


def summarize(root):
    with os.scandir(root) as entries:
        names = {entry.name for entry in entries if entry.is_file(follow_symlinks=False)}
    bad = []
    channels = {}
    distinct = {}
    for channel in CHANNELS:
        channels[channel], distinct[channel] = channel_summary(root, channel, names, bad)
    apply_state(root, channels, distinct, bad)
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    try:
        result = summarize(Path(args[0]))
    except OSError:
        return 2
    print(json.dumps(result, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
